import { useComCodeState } from '~/entities/comcode/lib/use-comcode-state';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { ComCodeParams } from '~/entities/comcode/model/types';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

type ResultContainerProps = {
  trnscTypeCd: TrnscTypeCd;
  children: React.ReactNode;
  useBenefit?: boolean;
  benefitChildren?: React.ReactNode;
};

export const ResultContainer = ({ trnscTypeCd, children, useBenefit, benefitChildren }: ResultContainerProps) => {
  const { comCode } = useComCodeState(COM_CODE.TRANSACTION_TYPE);
  const typeInfo = comCode?.hash?.[trnscTypeCd as unknown as keyof ComCodeParams];
  const trnscTypeName = typeInfo?.cdValueNm;

  return (
    <div className="exc-result">
      <div className="exc-result-list">
        <ul>
          <li className="exc-type">
            <span>{i18n.t('transactionType')}</span>
            <b>{trnscTypeName}</b>
          </li>
          {children}
        </ul>
      </div>
      {useBenefit && (
        <>
          <span style={{ margin: '15px 0px 5px 0px', fontSize: '15px' }}>
            <b>적용혜택</b>
          </span>
          <div className="exc-result-list">
            <ul>{benefitChildren}</ul>
          </div>
        </>
      )}
      <p className="trans-info">{i18n.t('text:transactionInfo')}</p>
    </div>
  );
};
